import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { ExploreFurther } from 'components';
import { usePageFilterApplied, usePageFilterQuickFiltersForm } from 'hooks';

import { WATCH_TOWER_PAGE_NAME } from '../../../constants';
import { buildWatchTowerExploreFurtherFilterQuery } from '../../../utils';

export const WatchTowerExploreFurtherSection: React.FC = () => {
  const { formatMessage } = useIntl();
  const { applied } = usePageFilterApplied(WATCH_TOWER_PAGE_NAME);
  const { quickForm } = usePageFilterQuickFiltersForm(WATCH_TOWER_PAGE_NAME);
  const isVolumeKpi = (applied.kpis as string | undefined) === 'volume';

  const filterQueryString = useMemo(
    () =>
      buildWatchTowerExploreFurtherFilterQuery({ ...applied, ...quickForm }),
    [applied, quickForm],
  );

  const cards = useMemo(
    () => [
      {
        title: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.performanceTool.title',
          defaultMessage: 'Financial Data',
        }),
        description: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.performanceTool.description',
          defaultMessage:
            'Enables multi-dimensional analysis of financial performance across key business metrics and hierarchies.',
        }),
        linkLabel: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.performanceTool.linkLabel',
          defaultMessage: 'Go to Performance Tool',
        }),
        linkHref: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.performanceTool.linkHref',
          defaultMessage: '/value-creation/performance-tool',
        }),
        abbreviation: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.performanceTool.abbreviation',
          defaultMessage: 'PT',
        }),
        enabled: true,
      },
      {
        title: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.commercialResults.title',
          defaultMessage: 'Commercial Data',
        }),
        description: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.commercialResults.description',
          defaultMessage:
            'Continue analyzing country performance across business dimensions, such as channel, pack type, region, and more.',
        }),
        linkLabel: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.commercialResults.linkLabel',
          defaultMessage: 'Go to Commercial Results',
        }),
        linkHref: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.commercialResults.linkHref',
          defaultMessage: '/value-creation/commercial-results',
        }),
        abbreviation: formatMessage({
          id: 'ValueCreation.WatchTower.exploreFurther.commercialResults.abbreviation',
          defaultMessage: 'CR',
        }),
        enabled: isVolumeKpi,
      },
    ],
    [formatMessage, isVolumeKpi],
  );

  return (
    <ExploreFurther
      filterPageName={WATCH_TOWER_PAGE_NAME}
      dataTestId={WATCH_TOWER_PAGE_NAME}
      filterQueryString={filterQueryString}
      cards={cards}
    />
  );
};
